interface UserPreferences {
  theme: string;
  notifications: boolean;
  language: string;
}

async function getUserPreferences(): Promise<UserPreferences> {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    });
    if (!res.ok) {
      throw new Error('Failed to fetch user preferences');
    }
    return res.json();
  } catch (error) {
    console.error('Error fetching preferences:', error);
    // Return default preferences on error
    return {
      theme: 'system',
      notifications: true,
      language: 'en',
    };
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div>
      <h2>User Dashboard</h2>
      <p>Theme: {preferences.theme}</p>
      <p>Notifications: {preferences.notifications ? 'Enabled' : 'Disabled'}</p>
      <p>Language: {preferences.language}</p>
    </div>
  );
}

